class VBase {
public:
    // Requires VTable creation (VPTR added to object layout)
    virtual void func_1() {}
    virtual void func_2() {}
};

class VDerived : public VBase {
public:
    // Overrides VTable entry for func_1
    void func_1() override {}
    // VTable entry 2 still points to VBase::func_2
};

// Pointer of base type holds derived object
VBase* ptr = new VDerived();

// Dynamic dispatch via VPTR -> VTable lookup
ptr->func_1(); // Calls VDerived::func_1
ptr->func_2(); // Calls VBase::func_2

delete ptr;
